class One {
  static Character _varname = 'a';
  static java.util.List<Call> _calls = new java.util.ArrayList<Call>();
  static java.util.Map<One,Character> _instances = new java.util.HashMap<One,Character>();

  private int field = 0;

  One(int f) {
    field = f;
    //
    _instances.put(this, _varname);
    _varname++;
    _calls.add(new Call(_instances.get(this),
      true,
      new Object() {}
        .getClass()
        .getEnclosingConstructor()
        .getName(),
      new Object[]{f},
      null));
  }

  void add(One other) {
    field = field + other.field;
    //
    _calls.add(new Call(_instances.get(this),
      false,
      new Object() {}
        .getClass()
        .getEnclosingMethod()
        .getName(),
      new Object[]{other},
      null));  
  }

  public void print() {
      System.out.println(field);
    //
    _calls.add(new Call(_instances.get(this),
      false,
      new Object() {}
        .getClass()
        .getEnclosingMethod()
        .getName(),
      new Object[] {},
      null));  
  }

  public String toString() {
    return _instances.get(this).toString();
  }
}

{{ STUDENT_ANSWER }}

class Call {
  Character target;
  Boolean isConstructor;
  String method;
  Object[] args;
  Object result;

  public Call(Character target, Boolean isConstructor, String method, Object[] args, Object result) {
    this.target = target;
    this.isConstructor = isConstructor;
    this.method = method;
    this.args = args;
    this.result = result;
  }

  public String toString() {
    StringBuilder s = new StringBuilder();
    if(isConstructor && method != null) {
        s.append(method.toString() + " ");
    }
    if(target != null) {
      s.append(target.toString());
    }
    if(isConstructor) {
      if(method != null) {
        s.append(" = new " + method.toString());
      }
    } else {
      if(method != null) {
        s.append("." + method.toString());
      }
    }
    if(args != null) {
      s.append("(");
      for(int i=0; i < args.length; i++) {
        s.append(args[i].toString());
        if(i < args.length-1) {
          s.append(",");
        }
      }
      s.append(")");
    }
    if(result != null) {
      s.append(" -> " + result.toString());
    }
    s.append(";");
    return s.toString();
  }
}

