class One {
  private int field = 0;

  One(int f) {
    field = f;
    //
    CallLog.addInstance(this);
    CallLog.addCall(this,
    true,
    new Object() {}
      .getClass()
      .getEnclosingClass()
      .getName(),
    new Object() {}
      .getClass()
      .getEnclosingConstructor()
      .getName(),
      new Object[] { f },
      null);  }

  void add(One other) {
    field = field + other.field;
    //
    CallLog.addCall(this,
    false,
    new Object() {}
      .getClass()
      .getEnclosingClass()
      .getName(),
    new Object() {}
      .getClass()
      .getEnclosingMethod()
      .getName(),
      new Object[] { other },
      null);
  }

  public int _getField() {
      return field;
